/**
 * A stand-in for Forma, for building themes in a plain browser.
 *
 * It answers from `library.json`: the real engine's output for the repository's fixture
 * library, regenerated by `cargo run -p forma-core --example mock_snapshot`. What a theme sees
 * here is what Forma would send. Favourites, settings and play stats change in memory;
 * views are a snapshot, so a new favourite does not move into the Favourites view.
 */
import type { Backend } from '../backend.js';
import { type ErrorCode, FormaError } from '../errors.js';
import type {
  Browse,
  DefaultView,
  Game,
  GameEnd,
  GameStart,
  LibraryChanged,
  NetplayRoom,
  RaGame,
  RaUser,
  SystemSummary,
  ThemeInfo,
  Unsubscribe,
  ViewInfo
} from '../types.js';
import data from './library.json' with { type: 'json' };

export interface MockOptions {
  /** How long a mock game "plays" before `game:end`. */
  playMs?: number;
  /** Permissions the mock pretends the theme declared, e.g. `settings.system`. */
  permissions?: string[];
  /** Pretend RetroAchievements is set up (default) or not. */
  ra?: boolean;
}

interface Snapshot {
  apiVersion: string;
  systems: SystemSummary[];
  views: ViewInfo[];
  games: Game[];
  browse: Record<string, Browse>;
  ra: { user: RaUser; games: Record<string, RaGame> };
  lobby: NetplayRoom[];
}

const snapshot = data as unknown as Snapshot;

type Handler = (payload: unknown) => void;

function fail(code: ErrorCode, message: string): never {
  throw new FormaError(code, message);
}

/** Lower-case without accents, for search the way SQLite's FTS does it. */
function fold(s: string): string {
  return s
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase();
}

export function mockBackend(options: MockOptions = {}): Backend {
  const playMs = options.playMs ?? 1500;
  const permissions = new Set(options.permissions ?? []);
  const games = new Map<number, Game>(snapshot.games.map((g) => [g.id, structuredClone(g)]));
  const settings = new Map<string, unknown>();
  const listeners = new Map<string, Set<Handler>>();
  let defaultView: string | null = null;
  let playing = false;

  const emit = (event: string, payload: unknown) => {
    for (const handler of listeners.get(event) ?? []) handler(payload);
  };

  const mediaUrl = (gameId: number, kind: string): string =>
    kind === 'video' ? '' : placeholder(games.get(gameId)?.name ?? `Game ${gameId}`, kind);

  /** A labelled placeholder image, so a theme's layout can be judged without real media. */
  function placeholder(name: string, kind: string): string {
    const svg =
      `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300">` +
      `<rect width="100%" height="100%" fill="#2a2d3a"/>` +
      `<text x="50%" y="50%" fill="#e8e9ee" font-family="sans-serif" font-size="22" ` +
      `text-anchor="middle">${escapeXml(name)}</text>` +
      `<text x="50%" y="62%" fill="#8a8d99" font-family="sans-serif" font-size="14" ` +
      `text-anchor="middle">${escapeXml(kind)}</text></svg>`;
    return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  }

  /** The live copy of a game, with media as URLs, as the app sends it. */
  const present = (game: Game): Game => {
    const live = games.get(game.id) ?? game;
    const media: Game['media'] = {};
    for (const kind of Object.keys(live.media) as (keyof Game['media'])[]) {
      const url = mediaUrl(live.id, kind);
      if (url) media[kind] = url;
    }
    return { ...live, media };
  };

  /** RetroAchievements media in the snapshot is `ra-media/<path>`; draw a placeholder. */
  const raMedia = <T>(value: T): T =>
    JSON.parse(JSON.stringify(value), (_key, v: unknown) =>
      typeof v === 'string' && v.startsWith('ra-media/')
        ? placeholder(v.split('/').pop()!, 'badge')
        : v
    ) as T;
  const fetched = <T>(data: T) => ({
    data: raMedia(data),
    stale: false,
    fetchedAt: new Date().toISOString().slice(0, 19)
  });
  const raConfigured = () => {
    if (options.ra === false) {
      fail(
        'notConfigured',
        'set your RetroAchievements web API key as the Forma setting ra.apiKey'
      );
    }
  };

  const settingKey = (key: string, scope: unknown): string => {
    if (scope === 'system') {
      if (!permissions.has('settings.system')) {
        fail('permissionDenied', 'theme `mock` needs the `settings.system` permission');
      }
      return key;
    }
    return `theme.mock.${key}`;
  };

  const commands: Record<string, (args: Record<string, unknown>) => unknown> = {
    sdk_api_version: () => snapshot.apiVersion,
    theme_ready: () => null,
    library_systems: () => snapshot.systems,
    library_game: ({ id }) => {
      const game = games.get(id as number);
      return game ? present(game) : null;
    },
    library_search: ({ query, limit }) => {
      const words = fold(String(query)).split(/\s+/).filter(Boolean);
      if (words.length === 0) return [];
      return [...games.values()]
        .filter((g) => !g.hidden)
        .filter((g) => {
          const text = fold([g.name, g.description, g.developer, g.publisher].join(' '));
          const tokens = text.split(/[^\p{L}\p{N}]+/u);
          return words.every((w) => tokens.some((t) => t.startsWith(w)));
        })
        .slice(0, (limit as number | undefined) ?? 50)
        .map(present);
    },
    library_set_favorite: ({ id, favorite }) => {
      const game = games.get(id as number) ?? fail('notFound', `no game with id ${String(id)}`);
      game.favorite = Boolean(favorite);
      emit('library:changed', { systems: [game.system] } satisfies LibraryChanged);
      return null;
    },
    nav_views: () => snapshot.views,
    nav_browse: ({ view, path, page }) => {
      if (!snapshot.views.some((v) => v.id === view))
        fail('notFound', `no view \`${String(view)}\``);
      const key = JSON.stringify([view, ...((path as string[] | undefined) ?? [])]);
      const found =
        snapshot.browse[key] ?? fail('invalid', `no such path in view \`${String(view)}\``);
      return paginate(found, page as { offset: number; limit: number } | undefined, present);
    },
    nav_default_view: (): DefaultView => ({ id: defaultView ?? 'systems', notes: [] }),
    nav_set_default_view: ({ id }) => {
      if (id !== null && id !== undefined && !snapshot.views.some((v) => v.id === id)) {
        fail('notFound', `no view ${JSON.stringify(id)}`);
      }
      defaultView = (id as string | null) ?? null;
      return null;
    },
    settings_get: ({ key, scope }) => settings.get(settingKey(String(key), scope)) ?? null,
    settings_set: ({ key, value, scope }) => {
      const k = settingKey(String(key), scope);
      if (value === null || value === undefined) settings.delete(k);
      else settings.set(k, structuredClone(value));
      return null;
    },
    themes_list: (): ThemeInfo[] => [
      {
        id: 'mock',
        name: 'Mock',
        version: null,
        origin: 'user',
        permissions: [...permissions],
        current: true,
        unavailable: null
      }
    ],
    themes_select: ({ id }) =>
      id === 'mock' ? null : fail('notFound', `theme \`${String(id)}\` is not available`),
    input_controllers: () => [],
    ra_user: () => {
      raConfigured();
      return fetched(snapshot.ra.user);
    },
    ra_game: ({ id }) => {
      raConfigured();
      const game = snapshot.ra.games[String(id)];
      if (!game) fail('notFound', `no RetroAchievements id is known for game ${String(id)} yet`);
      return fetched(game);
    },
    netplay_lobby: () => fetched(snapshot.lobby),
    system_quit: () => power(),
    system_power: () => power(),
    launch_game: ({ id }) => {
      if (playing) fail('busy', 'a game is already running');
      const game = games.get(id as number) ?? fail('launch', `no game with id ${String(id)}`);
      playing = true;
      emit('game:start', {
        type: 'game:start',
        gameId: game.id,
        system: game.system,
        name: game.name
      } satisfies GameStart);
      setTimeout(() => {
        playing = false;
        game.playCount += 1;
        game.lastPlayed = new Date().toISOString().slice(0, 19);
        game.gameTime += Math.round(playMs / 1000);
        emit('game:end', {
          type: 'game:end',
          gameId: game.id,
          seconds: Math.round(playMs / 1000),
          exitCode: 0,
          error: null
        } satisfies GameEnd);
        emit('library:changed', { systems: [game.system] } satisfies LibraryChanged);
      }, playMs);
      return null;
    }
  };

  function power(): never {
    if (!permissions.has('system.power')) {
      fail('permissionDenied', 'theme `mock` needs the `system.power` permission');
    }
    fail('unsupported', 'the mock cannot quit, restart or shut down');
  }

  return {
    kind: 'mock',
    invoke<T>(command: string, args: Record<string, unknown> = {}): Promise<T> {
      const run = commands[command];
      if (!run) return Promise.reject(new FormaError('notFound', `unknown command ${command}`));
      try {
        return Promise.resolve(run(args) as T);
      } catch (error) {
        return Promise.reject(FormaError.from(error));
      }
    },
    listen<T>(event: string, handler: (payload: T) => void): Unsubscribe {
      const set = listeners.get(event) ?? new Set<Handler>();
      listeners.set(event, set);
      set.add(handler as Handler);
      return () => set.delete(handler as Handler);
    },
    mediaUrl
  };
}

function paginate(
  browse: Browse,
  page: { offset: number; limit: number } | undefined,
  present: (g: Game) => Game
): Browse {
  const offset = page?.offset ?? 0;
  const limit = page?.limit ?? 200;
  const listing = browse.listing;
  switch (listing.kind) {
    case 'branches':
      return browse;
    case 'groups':
      return {
        ...browse,
        listing: { ...listing, items: listing.items.slice(offset, offset + limit) }
      };
    case 'games':
      return {
        ...browse,
        listing: { ...listing, items: listing.items.slice(offset, offset + limit).map(present) }
      };
  }
}

function escapeXml(s: string): string {
  return s.replace(
    /[<>&"]/g,
    (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[c]!
  );
}
